  CONSTRAINT `ck_user_account_lock` CHECK ((`failed_login_count` >= 0)),
  CONSTRAINT `ck_user_account_password` CHECK ((((`account_status` = _utf8mb4'PENDING_ACTIVATION') and (`password_hash` is null)) or ((`account_status` in (_utf8mb4'ACTIVE',_utf8mb4'DISABLED')) and (`password_hash` is not null)))),
