  CONSTRAINT `ck_user_account_status` CHECK ((`account_status` in (_utf8mb4'PENDING_ACTIVATION',_utf8mb4'ACTIVE',_utf8mb4'DISABLED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
