INSERT INTO `english_grammar_course` (`id`, `title`, `subtitle`, `summary`, `introduction`, `roadmap_markdown`, `cover_media_id`, `seo_title`, `seo_description`, `publish_status`, `published_at`, `created_at`, `updated_at`) VALUES (1,'英语语法完整教程','从语言基础单位到复杂句法分析','以现代英语语法结构为核心，从词法、短语和句子结构逐步扩展到动词、从句、非谓语、特殊句式与语篇级分析。','建立完整英语语法知识框架，理解英语句子的生成逻辑，掌握复杂句子的结构分析能力，并支撑高级英文阅读与表达。','1. 词法基础\n2. 短语结构\n3. 基本句型\n4. 动词系统\n5. 从句体系\n6. 非谓语体系\n7. 特殊句式\n8. 复杂句分析\n9. 综合应用',NULL,'英语语法完整教程｜星雨笔录','从词法到语篇，系统建立英语语法知识框架与复杂句分析能力。','PUBLISHED','2026-09-01 11:48:08.756529','2026-09-01 11:48:08.756529','2026-09-01 11:48:08.756529');

INSERT INTO `english_grammar_section` (`id`, `course_id`, `title`, `sort_order`, `created_at`, `updated_at`) VALUES (1,1,'第一章 英语语法总论',10,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(2,1,'第二章 词法体系（Word Level）',20,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(3,1,'第三章 短语结构体系',30,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(4,1,'第四章 基本句型体系',40,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(5,1,'第五章 动词高级体系',50,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(6,1,'第六章 从句体系',60,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(7,1,'第七章 非谓语动词体系',70,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(8,1,'第八章 特殊句式体系',80,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(9,1,'第九章 复杂句法分析体系',90,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591'),(10,1,'第十章 高级语法综合应用',100,'2026-09-01 11:48:08.757591','2026-09-01 11:48:08.757591');

INSERT INTO `english_grammar_lesson` (`id`, `course_id`, `section_id`, `title`, `slug`, `summary`, `body_markdown`, `publish_status`, `sort_order`, `published_at`, `created_at`, `updated_at`) VALUES (1,1,1,'语言结构基础','1-1','英语语言组成层次、词与句子的关系、语法规则和句法结构特点。','## 学习内容\n\n- 英语语言组成层次\n- 词、短语、分句、句子的关系\n- 语法规则的基本作用\n- 英语句法结构特点','PUBLISHED',10,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(2,1,1,'英语句子分析方法','1-2','句子成分、主干与修饰成分、层级结构及语法树基础。','## 学习内容\n\n- 句子成分划分\n- 主干与修饰成分识别\n- 层级结构分析方法\n- 语法树基本概念','PUBLISHED',20,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(3,1,2,'名词系统','2-1','名词分类、数与所有格，以及名词的句法功能。','## 学习内容\n\n- 名词分类\n- 可数与不可数名词\n- 名词单复数变化\n- 名词所有格\n- 名词句法功能','PUBLISHED',10,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(4,1,2,'代词系统','2-2','人称、物主、反身、指示、疑问、不定及关系代词。','## 学习内容\n\n- 人称代词\n- 物主代词\n- 反身代词\n- 指示代词\n- 疑问代词\n- 不定代词\n- 关系代词','PUBLISHED',20,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(5,1,2,'冠词系统','2-3','不定冠词、定冠词、零冠词及其使用逻辑。','## 学习内容\n\n- 不定冠词\n- 定冠词\n- 零冠词\n- 冠词使用逻辑','PUBLISHED',30,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(6,1,2,'动词系统基础','2-4','实义、系、助、情态动词及及物性。','## 学习内容\n\n- 实义动词\n- 系动词\n- 助动词\n- 情态动词\n- 及物动词与不及物动词','PUBLISHED',40,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(7,1,2,'形容词系统','2-5','形容词功能、位置、比较等级与多形容词排序。','## 学习内容\n\n- 形容词功能\n- 形容词位置\n- 比较级\n- 最高级\n- 多形容词排序','PUBLISHED',50,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(8,1,2,'副词系统','2-6','副词分类、修饰关系及位置变化。','## 学习内容\n\n- 副词分类\n- 副词修饰关系\n- 副词位置变化','PUBLISHED',60,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464'),(9,1,2,'介词系统','2-7','时间、地点、方式介词与介词短语结构。','## 学习内容\n\n- 时间介词\n- 地点介词\n- 方式介词\n- 介词短语结构','PUBLISHED',70,'2026-09-01 11:48:08.758464','2026-09-01 11:48:08.758464','2026-09